import { test, expect } from '@playwright/test';

test.describe('Dropdown Selection', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dropdown');
  });

  test('should select an option from the dropdown and apply the value', async ({ page }) => {
    // Verify dropdown initially shows disabled prompt
    const dropdown = page.getByRole('combobox', { name: /Please select an option/i });
    await expect(dropdown).toBeVisible();
    await expect(dropdown).toHaveValue('option1');

    // Select the option with text 'Option 2'
    const option2 = page.getByRole('option', { name: /Option 2/i });
    await option2.click();

    // Verify the select element now has the correct value
    await expect(dropdown).toHaveValue('option2');

    // Verify the selected option is visible and highlighted
    await expect(option2).toBeVisible();
    await expect(option2).toHaveAttribute('aria-selected', 'true');
  });

  test('should handle selecting the first and last options', async ({ page }) => {
    // Select the first option
    const option1 = page.getByRole('option', { name: /Option 1/i });
    await option1.click();

    // Verify the select element has the correct value
    await expect(page.getByRole('combobox', { name: /Please select an option/i })).toHaveValue('option1');

    // Select the last option
    const optionLast = page.getByRole('option', { name: /Option 4/i });
    await optionLast.click();

    // Verify the select element has the correct value
    await expect(page.getByRole('combobox', { name: /Please select an option/i })).toHaveValue('option4');

    // Verify the last option is selected
    await expect(optionLast).toHaveAttribute('aria-selected', 'true');
  });
});
